CREATE TABLE ibexa_media (contentobject_attribute_id INT DEFAULT 0 NOT NULL, version INT DEFAULT 0 NOT NULL, controls VARCHAR(50) DEFAULT NULL, filename VARCHAR(255) DEFAULT '' NOT NULL, has_controller INT DEFAULT 0, height INT DEFAULT NULL, is_autoplay INT DEFAULT 0, is_loop INT DEFAULT 0, mime_type VARCHAR(50) DEFAULT '' NOT NULL, original_filename VARCHAR(255) DEFAULT '' NOT NULL, pluginspage VARCHAR(255) DEFAULT NULL, quality VARCHAR(50) DEFAULT NULL, width INT DEFAULT NULL, PRIMARY KEY(contentobject_attribute_id, version)) DEFAULT CHARACTER SET utf8 COLLATE `utf8_unicode_ci` ENGINE = InnoDB;
